const e=t=>t.toFixed(Math.abs(t)>=100?0:1).replace(/\.0$/,"");function r(t){if(!Number.isFinite(t))return"—";const i=["B","KB","MB","GB","TB"];let n=0;for(;Math.abs(t)>=1e3&&n<i.length-1;)t/=1e3,n++;return`${n===0?Math.round(t):e(t)} ${i[n]}`}function o(t){if(!Number.isFinite(t))return"—";const i=["","K","M","B"];let n=0;for(;Math.abs(t)>=1e3&&n<i.length-1;)t/=1e3,n++;return`${n===0?Math.round(t):e(t)}${i[n]}`}function s(t,i=!1){const n=new Date(t);return Number.isFinite(n.getTime())?n.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",...i?{second:"2-digit"}:{},hourCycle:"h23"}):"—"}export{r as a,s as b,o as f};
